const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs/promises'),path=require('node:path'),os=require('node:os');
const removal=require('../../core/packages/removal.cjs'),jobs=require('../../core/packages/jobs.cjs');
async function fixture(t){const root=await fs.mkdtemp(path.join(os.tmpdir(),'iz2s-unload-'));t.after(()=>fs.rm(root,{recursive:true,force:true}));const catalog=path.join(root,'session/apps'),pc=path.join(root,'modules/demo');await fs.mkdir(path.join(catalog,'demo'),{recursive:true});await fs.mkdir(pc,{recursive:true});await fs.writeFile(path.join(pc,'demo.izm'),'installed PC package');await fs.writeFile(path.join(catalog,'demo/app.json'),JSON.stringify({id:'demo'}));return {root,catalog,pc,state:path.join(root,'state'),installed:[{id:'demo',name:'Demo'}]};}
test('PC and console removal use the same deduplicated queue',async t=>{const f=await fixture(t);const [first]=await removal.queue(f.state,['demo'],f.installed,'browser');const [second]=await removal.queue(f.state,['demo'],f.installed,'console');assert.equal(first.id,second.id);assert.equal(first.operation,'remove');assert.equal((await jobs.all(f.state)).length,1);assert.equal(await fs.readFile(path.join(f.pc,'demo.izm'),'utf8'),'installed PC package');});
test('unloading removes only the session copy; PC package can be loaded again',async t=>{const f=await fixture(t);assert.deepEqual(await removal.remove(f.catalog,'demo'),{id:'demo',removed:true});await assert.rejects(fs.stat(path.join(f.catalog,'demo')),/ENOENT/);assert.equal(await fs.readFile(path.join(f.pc,'demo.izm'),'utf8'),'installed PC package');assert.deepEqual(await fs.readdir(f.catalog),[]);await fs.mkdir(path.join(f.catalog,'demo'));await fs.writeFile(path.join(f.catalog,'demo/app.json'),JSON.stringify({id:'demo'}));assert.equal((await removal.remove(f.catalog,'demo')).removed,true);});
test('invalid IDs and unloaded modules cannot create jobs',async t=>{const f=await fixture(t);for(const ids of [[],['../demo'],['missing'],['demo','missing']])await assert.rejects(removal.queue(f.state,ids,f.installed,'browser'));assert.equal((await jobs.all(f.state)).length,0);await assert.rejects(removal.remove(f.catalog,'../demo'));});
test('symlink or mismatched catalog entries cannot delete outside the session',async t=>{const f=await fixture(t);await fs.symlink(f.pc,path.join(f.catalog,'linked'));await assert.rejects(removal.remove(f.catalog,'linked'),/session catalog/);await fs.writeFile(path.join(f.catalog,'demo/app.json'),JSON.stringify({id:'other'}));await assert.rejects(removal.remove(f.catalog,'demo'),/identity/);assert.equal(await fs.readFile(path.join(f.pc,'demo.izm'),'utf8'),'installed PC package');});
test('conflicting load/remove operations are not silently interchanged',async t=>{const f=await fixture(t);await jobs.create(f.state,{id:'demo',name:'Demo',file:'demo.izm'},'browser');await assert.rejects(removal.queue(f.state,['demo'],f.installed,'console'),/already queued/);assert.equal((await jobs.all(f.state))[0].operation,'load');});
test('queued operations wait for an idle menu, including built-in apps and launch fades',async()=>{const state=Buffer.alloc(1024),mode=Buffer.alloc(4),rpc={read:async()=>mode};assert.equal(await removal.atMenu({},state,rpc,0),true);assert.equal(await removal.atMenu({active:{id:'demo'}},state,rpc,0),false);mode.writeUInt32LE(2);assert.equal(await removal.atMenu({},state,rpc,0),false);mode.writeUInt32LE(0);state.writeFloatLE(1,964);assert.equal(await removal.atMenu({},state,rpc,0),false);state.writeFloatLE(0,964);state.writeUInt32LE(1,1012);assert.equal(await removal.atMenu({},state,rpc,0),false);});
